#!/bin/sh
# Installer for @TOOL@: curl -fsSL @TOOL_URL@/install.sh | sh
# Generated by tools.klar.ws. Optional environment variables:
#   @ENV@_VERSION      version to install (default: latest)
#   @ENV@_INSTALL_DIR  target directory (default: ~/.local/bin)
#   @ENV@_BASE_URL     download location (default: @TOOL_URL@)
set -eu

tool='@TOOL@'
bin='@BIN@'
base=${@ENV@_BASE_URL:-'@TOOL_URL@'}
install_dir=${@ENV@_INSTALL_DIR:-"$HOME/.local/bin"}
version=${@ENV@_VERSION:-}

say() { printf '%s\n' "$*" >&2; }
fail() { say "$tool installer: $*"; exit 1; }
command -v curl >/dev/null 2>&1 || fail "curl is required"

case "$(uname -s)" in
Linux) os=unknown-linux-gnu ;;
Darwin) os=apple-darwin ;;
*) fail "unsupported operating system: $(uname -s)" ;;
esac
case "$(uname -m)" in
x86_64 | amd64) arch=x86_64 ;;
arm64 | aarch64) arch=aarch64 ;;
*) fail "unsupported architecture: $(uname -m)" ;;
esac

if [ -z "$version" ]; then
	version=$(curl -fsSL "$base/latest") || fail "could not determine the latest version"
fi
version=$(printf '%s' "${version#v}" | tr -d '[:space:]')
asset="$tool-$arch-$os.tar.gz"
url="$base/v$version"

tmp=$(mktemp -d "${TMPDIR:-/tmp}/$tool-install.XXXXXX")
trap 'rm -rf "$tmp"' EXIT INT TERM

curl -fsSL "$url/checksums.txt" -o "$tmp/checksums.txt" || fail "version $version not found"
expected=$(awk -v a="$asset" '$2 == a || $2 == "*" a { print $1; exit }' "$tmp/checksums.txt")
[ -n "$expected" ] || fail "no build of $tool $version for $arch-$os"
curl -fsSL "$url/$asset" -o "$tmp/$asset"
if command -v sha256sum >/dev/null 2>&1; then
	actual=$(sha256sum "$tmp/$asset" | awk '{print $1}')
elif command -v shasum >/dev/null 2>&1; then
	actual=$(shasum -a 256 "$tmp/$asset" | awk '{print $1}')
else
	fail "sha256sum or shasum is required"
fi
[ "$actual" = "$expected" ] || fail "checksum verification failed for $asset"

mkdir -p "$tmp/x" "$install_dir"
tar -xzf "$tmp/$asset" -C "$tmp/x"
src=$(find "$tmp/x" -type f -name "$bin" | head -n 1)
[ -n "$src" ] || fail "$bin not found in $asset"
install -m 0755 "$src" "$install_dir/$bin"
say "Installed $tool $version to $install_dir/$bin"
case ":$PATH:" in *":$install_dir:"*) ;; *) say "Add $install_dir to your PATH." ;; esac
